static bool sgCleanupBeforeExit(bool nonBlocking) {
    if (g_sgCleanupDone) return true;
    std::unique_lock<std::mutex> opLock(g_sgOpMtx, std::defer_lock);
    if (nonBlocking) {
        if (!opLock.try_lock()) {
            sgRecordFact("sleep-exit-cleanup-deferred", {
                {"reason", "sleep-worker-busy"}
            });
            return false;
        }
    } else {
        opLock.lock();
    }
    // A completed flag is published only after recovery and marker persistence.
    if (g_sgCleanupDone) return true;
    sgCancelWakeGameRecoveryUnlocked("application-exit");
    sgRecordFact("sleep-exit-cleanup-start");
    // 正常退出必须解除所有由本程序挂起的进程。
    SgSleepTarget currentTarget;
    if (sgReadSleepTarget(currentTarget) && currentTarget.markerOwned)
        (void)sgResumeSleepTargetUnlocked(currentTarget.powerGeneration, false);
    SgResumeResult rr = sgResumeTrackedAllUnlocked();
    (void)rr;
    // 若仍有标记，说明恢复失败；允许 WM_DESTROY/消息循环退出再重试一次。
    const bool pending = sgHasMarkerFiles(SG_SLEEP_LEASE_DIR) ||
        sgHasMarkerFiles(SG_MANUAL_DIR);
    const bool sessionClean = !pending && sessionMarkerMarkClean();
    g_sgCleanupDone = sessionClean;
    sgRecordFact("sleep-exit-cleanup-complete", {
        {"pendingMarkers", pending}, {"sessionClean", sessionClean}, {"resumed", rr.count}
    });
    g_sgInSuspend = false;
    return sessionClean;
}

